#!/usr/bin/env python3
"""One-time transfer of original pilot sources through GitHub's text editor.
No downloads, credentials or external textbook content. Removed after expansion.
"""
import base64,hashlib,json,lzma
from pathlib import Path
PAYLOAD = ""
EXPECTED = "5668c38d586ed249083ae93c9c5c580dc32b62e7271daa640fcb011dab817ebc"
raw=lzma.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(raw).hexdigest()==EXPECTED
root=Path.cwd().resolve()
for name,content in json.loads(raw).items():
    path=(root/name).resolve()
    assert path.is_relative_to(root) and ".git" not in path.parts
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(content,encoding="utf-8")
print("Materialized original source files; use tools/build_thermal_pilot.py to build.")
